import json,glob,datetime as dt,holidays,calendar
LANDS=['BW','BY','BE','BB','HB','HH','HE','MV','NI','NW','RP','SL','SN','ST','SH','TH']
HC={}
def hol(land,y):
    k=(land,y)
    if k not in HC: HC[k]=holidays.Germany(subdiv=land,years=y) if land else holidays.Germany(years=y)
    return HC[k]
def isholi(d,land): return d in hol(land,d.year)
def work(d,land): return d.weekday()<5 and not isholi(d,land)
def addm(d,n):
    y,m=divmod(d.month-1+n,12); y+=d.year; m+=1
    return dt.date(y,m,min(d.day,calendar.monthrange(y,m)[1]))
def fwd(d,n,u,land):
    if u=='days': return d+dt.timedelta(n)
    if u=='weeks': return d+dt.timedelta(7*n)
    if u=='months': return addm(d,n)
    x=d;c=0
    while c<n:
        x+=dt.timedelta(1)
        if u=='werktage' and x.weekday()<6 and not isholi(x,land): c+=1
        if u=='arbeitstage' and x.weekday()<5 and not isholi(x,land): c+=1
    return x
def back(d,n,u,land):
    x=d
    while fwd(x,n,u,land)>d: x-=dt.timedelta(1)
    return x
def run(frm,steps,land):
    d=dt.date.fromisoformat(frm)
    for s in steps:
        if s['op']=='forward': d=fwd(d,s['n'],s['unit'],land)
        elif s['op']=='back': d=back(d,s['n'],s['unit'],land)
        elif s['op']=='month_end':
            y,m=divmod(d.month-1+s['n'],12); y+=d.year; m+=1; d=dt.date(y,m,calendar.monthrange(y,m)[1])
        if s['shift']:
            step=-1 if s['op']=='back' else 1
            while not work(d,land): d+=dt.timedelta(step)
    return d.isoformat()
bad=0
for f in sorted(glob.glob('sealed/*.json')):
